-- About Us page: seed storefront content + show/hide layout into site_settings.
-- Run via the migrator:  php migrate.php   (records itself in schema_migrations)
--
-- Adds two site_settings keys read by the React storefront About page and
-- editable in Admin → Settings → About Page:
--   * aboutSections — the show/hide + reorder layout the admin toggles (Page Layout tab)
--   * aboutConfig   — hero, story, stats, milestones, core values, team, why-trust,
--                     mission/vision, testimonials, certifications, bottom CTA
--
-- INSERT IGNORE is used on purpose: if a key already exists (admin already
-- customised it), the existing value is kept and this row is skipped. To force
-- a reset to these defaults, delete the key first or edit it in the admin panel.


-- Safety: ensure the settings table exists (matches database_bestsellers_fix.sql).
CREATE TABLE IF NOT EXISTS site_settings (
    skey       VARCHAR(100) PRIMARY KEY,
    svalue     LONGTEXT,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- 1) About page layout — the array the admin shows/hides & reorders.
--    A section is visible on the storefront unless "enabled":false.
INSERT IGNORE INTO site_settings (skey, svalue) VALUES
('aboutSections', '[{\"key\":\"hero\",\"label\":\"Hero\",\"enabled\":true},{\"key\":\"story\",\"label\":\"Our Story\",\"enabled\":true},{\"key\":\"stats\",\"label\":\"Stats Strip\",\"enabled\":true},{\"key\":\"milestones\",\"label\":\"Milestones\",\"enabled\":true},{\"key\":\"coreValues\",\"label\":\"Core Values\",\"enabled\":true},{\"key\":\"leadership\",\"label\":\"Leadership / Team\",\"enabled\":true},{\"key\":\"whyTrust\",\"label\":\"Why Trust Us\",\"enabled\":true},{\"key\":\"missionVision\",\"label\":\"Mission & Vision\",\"enabled\":true},{\"key\":\"testimonials\",\"label\":\"Testimonials\",\"enabled\":true},{\"key\":\"certifications\",\"label\":\"Certifications\",\"enabled\":true},{\"key\":\"whatWeOffer\",\"label\":\"What We Offer\",\"enabled\":true},{\"key\":\"cta\",\"label\":\"Bottom CTA\",\"enabled\":true},{\"key\":\"contactStrip\",\"label\":\"Contact Strip\",\"enabled\":true},{\"key\":\"socialStrip\",\"label\":\"Social Strip\",\"enabled\":true}]');

